import { Request, Response, NextFunction } from "express";

export interface RateLimiterOptions {
  windowMs?: number;
  maxRequests?: number;
}

interface ClientRecord {
  count: number;
  resetTime: number;
}

export function createRateLimiter(options: RateLimiterOptions = {}) {
  const windowMs = options.windowMs ?? 60 * 1000; // default: 1 minute
  const maxRequests = options.maxRequests ?? 100; // default: 100 requests per window

  const hits = new Map<string, ClientRecord>();

  // Helper to clear the stored store (useful for testing or manual resets)
  const resetStore = () => {
    hits.clear();
  };

  const middleware = (req: Request, res: Response, next: NextFunction) => {
    const key = req.ip || req.socket.remoteAddress || "unknown";
    const now = Date.now();

    let record = hits.get(key);

    if (!record || now >= record.resetTime) {
      record = {
        count: 0,
        resetTime: now + windowMs,
      };
    }

    record.count += 1;
    hits.set(key, record);

    const remaining = Math.max(0, maxRequests - record.count);
    const retryAfter = Math.ceil((record.resetTime - now) / 1000);

    res.setHeader("RateLimit-Limit", maxRequests);
    res.setHeader("RateLimit-Remaining", remaining);
    res.setHeader("RateLimit-Reset", Math.ceil(record.resetTime / 1000));

    if (record.count > maxRequests) {
      res.setHeader("Retry-After", retryAfter);
      res.status(429).json({
        error: "Too Many Requests",
        message: "Rate limit exceeded. Please try again later.",
        retryAfter,
      });
      return;
    }

    next();
  };

  middleware.resetStore = resetStore;

  return middleware;
}

export const rateLimiter = createRateLimiter();

