import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";
import request from "supertest";
import express from "express";
import { createRateLimiter } from "../src/middleware/rateLimiter.js";

describe("Rate Limiter Middleware", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("enforces rate limits when request limit is exceeded", async () => {
    const testLimiter = createRateLimiter({ windowMs: 60 * 1000, maxRequests: 3 });
    const app = express();
    app.use(testLimiter);
    app.get("/test", (_req, res) => res.json({ ok: true }));

    // Send 3 requests - should all succeed (200)
    for (let i = 0; i < 3; i++) {
      const res = await request(app).get("/test");
      expect(res.status).toBe(200);
      expect(res.headers["ratelimit-limit"]).toBe("3");
      expect(res.headers["ratelimit-remaining"]).toBe(String(2 - i));
    }

    // 4th request - should be rate limited (429)
    const rateLimitedRes = await request(app).get("/test");
    expect(rateLimitedRes.status).toBe(429);
    expect(rateLimitedRes.body).toEqual({
      error: "Too Many Requests",
      message: "Rate limit exceeded. Please try again later.",
      retryAfter: expect.any(Number),
    });
    expect(rateLimitedRes.headers["retry-after"]).toBeDefined();
  });

  it("resets window after configured duration", async () => {
    const windowMs = 5000; // 5 seconds
    const testLimiter = createRateLimiter({ windowMs, maxRequests: 2 });
    const app = express();
    app.use(testLimiter);
    app.get("/test", (_req, res) => res.json({ ok: true }));

    // Exhaust requests
    await request(app).get("/test");
    await request(app).get("/test");

    const blockedRes = await request(app).get("/test");
    expect(blockedRes.status).toBe(429);

    // Advance time past windowMs
    vi.advanceTimersByTime(windowMs + 100);

    // Request after window reset should succeed
    const resetRes = await request(app).get("/test");
    expect(resetRes.status).toBe(200);
    expect(resetRes.headers["ratelimit-remaining"]).toBe("1");
  });
});

