export function createRateLimiter(options: RateLimiterOptions = {}) {
  const windowMs = options.windowMs ?? 60 * 1000; // default: 1 minute
  const maxRequests = options.maxRequests ?? 100; // default: 100 requests per window

  const hits = new Map<string, ClientRecord>();

  // Periodically clean up expired entries to prevent memory leaks in long-running processes
  const cleanupTimer = setInterval(() => {
    const now = Date.now();
    for (const [key, record] of hits.entries()) {
      if (now >= record.resetTime) {
        hits.delete(key);
      }
    }
  }, windowMs);

  // Unref cleanup timer so it doesn't block node process exit
  if (cleanupTimer.unref) {
    cleanupTimer.unref();
  }

  const resetStore = () => {
    hits.clear();
  };

  const middleware = (req: Request, res: Response, next: NextFunction) => {
    const xForwardedFor = req.headers["x-forwarded-for"];
    const forwardedIp = typeof xForwardedFor === "string" 
      ? xForwardedFor.split(",")[0].trim() 
      : Array.isArray(xForwardedFor) 
      ? xForwardedFor[0].trim() 
      : undefined;

    const key = req.ip || forwardedIp || req.socket.remoteAddress || "127.0.0.1";
    const now = Date.now();

    let record = hits.get(key);

    if (!record || now >= record.resetTime) {
      record = {
        count: 0,
        resetTime: now + windowMs,
      };
    }

    record.count += 1;
    hits.set(key, record);

    const remaining = Math.max(0, maxRequests - record.count);
    const retryAfter = Math.max(1, Math.ceil((record.resetTime - now) / 1000));

    res.setHeader("RateLimit-Limit", maxRequests);
    res.setHeader("RateLimit-Remaining", remaining);
    res.setHeader("RateLimit-Reset", Math.ceil(record.resetTime / 1000));

    if (record.count > maxRequests) {
      res.setHeader("Retry-After", retryAfter);
      res.status(429).json({
        error: "Too Many Requests",
        message: "Rate limit exceeded. Please try again later.",
        retryAfter,
      });
      return;
    }

    next();
  };

  middleware.resetStore = resetStore;

  return middleware;
}

